# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KAREKÖKLÜ İFADELERDE ÇARPMA İŞLEMİ KURALLARI</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Temel Çarpma Kuralı</text>\n  <text x="187" y="112" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">a·kök(x) · b·kök(y) = (a · b)·kök(x · y)</text>\n  <text x="55" y="142" font-size="11.5" fill="#334155">• Katsayılar kendi arasında çarpılır, katsayı yazılır.</text>\n  <text x="55" y="166" font-size="11.5" fill="#334155">• Kök içleri kendi arasında çarpılır, kök içine yazılır.</text>\n  <text x="55" y="192" font-size="11.5" font-weight="bold" fill="#1d4ed8">Örnek: 3·kök(2) · 4·kök(5) = 12·kök(10)</text>\n  <text x="55" y="216" font-size="11.5" font-weight="bold" fill="#15803d">Örnek: 2·kök(3) · 5·kök(6) = 10·kök(18) = 30·kök(2)</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Doğal Sayı Yapan Çarpan</text>\n  <text x="512" y="112" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">kök(a) · kök(a) = kök(a²) = a</text>\n  <text x="380" y="142" font-size="11.5" fill="#334155">• İfade önce a·kök(b) biçimine getirilir.</text>\n  <text x="380" y="166" font-size="11.5" fill="#334155">• Kök içinde kalan b sayısını tam kare yapan</text>\n  <text x="390" y="184" font-size="11" fill="#475569">kök(b) veya k·kök(b) ifadeleri doğal sayı yapar.</text>\n  <text x="380" y="214" font-size="11.5" font-weight="bold" fill="#15803d">Örnek: kök(24) = 2·kök(6) → Çarpan: kök(6)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KAREKÖKLÜ İFADELERDE BÖLME VE PAYDAYI RASYONEL YAPMA</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Temel Bölme Kuralı</text>\n  <text x="187" y="112" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">[a·kök(x)] / [b·kök(y)] = (a / b)·kök(x / y)</text>\n  <text x="55" y="142" font-size="11.5" fill="#334155">• Katsayılar kendi arasında bölünür.</text>\n  <text x="55" y="166" font-size="11.5" fill="#334155">• Kök içindeki sayılar ortak kök içinde bölünür.</text>\n  <text x="55" y="192" font-size="11.5" font-weight="bold" fill="#a16207">Örnek: [12·kök(15)] / [3·kök(5)] = 4·kök(3)</text>\n  <text x="55" y="216" font-size="11.5" font-weight="bold" fill="#a16207">Örnek: kök(75) / kök(3) = kök(25) = 5</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Paydayı Rasyonel (Doğal Sayı) Yapma</text>\n  <text x="512" y="112" text-anchor="middle" font-size="13" font-weight="bold" fill="#9d174d">a / kök(b) = [a · kök(b)] / [kök(b) · kök(b)] = [a·kök(b)] / b</text>\n  <text x="380" y="142" font-size="11.5" fill="#334155">• Paydadaki köklü ifade ile kesir genişletilir.</text>\n  <text x="380" y="168" font-size="11.5" font-weight="bold" fill="#be185d">Örnek 1: 6 / kök(3) = 6·kök(3) / 3 = 2·kök(3)</text>\n  <text x="380" y="194" font-size="11.5" font-weight="bold" fill="#be185d">Örnek 2: 10 / kök(5) = 10·kök(5) / 5 = 2·kök(5)</text>\n  <text x="380" y="220" font-size="11" fill="#475569">Paydada karekök bırakılmaz, sadeleştirilir!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KAREKÖKLÜ İFADELERDE TOPLAMA VE ÇIKARMA İŞLEMLERİ</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kök İçleri Eşit Olan İfadeler</text>\n  <text x="187" y="110" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">a·kök(x) + b·kök(x) - c·kök(x) = (a + b - c)·kök(x)</text>\n  <text x="55" y="140" font-size="11.5" fill="#334155">• Kök içi aynen kalır, katsayılar toplanır/çıkarılır.</text>\n  <text x="55" y="166" font-size="11.5" font-weight="bold" fill="#1d4ed8">• 4·kök(7) + 5·kök(7) - 2·kök(7) = 7·kök(7)</text>\n  <text x="55" y="192" font-size="11.5" font-weight="bold" fill="#b91c1c">• Dikkat: kök(a) + kök(b) ≠ kök(a + b)</text>\n  <text x="65" y="214" font-size="11" fill="#475569">Örn: kök(9) + kök(16) = 3 + 4 = 7 (kök(25)=5 ile karıştırma!)</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kök İçlerini Eşitleme Yöntemi</text>\n  <text x="380" y="110" font-size="11.5" fill="#334155">• Kök içleri farklıysa önce a·kök(b) biçiminde yazılır.</text>\n  <text x="380" y="138" font-size="11.5" font-weight="bold" fill="#166534">Örnek: kök(12) + kök(27) - kök(3)</text>\n  <text x="390" y="162" font-size="11.5" fill="#334155">= 2·kök(3) + 3·kök(3) - 1·kök(3)</text>\n  <text x="390" y="186" font-size="11.5" font-weight="bold" fill="#15803d">= (2 + 3 - 1)·kök(3) = 4·kök(3)</text>\n  <text x="380" y="216" font-size="11" fill="#475569">Kök içleri eşitlenemiyorsa işlem olduğu gibi kalır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
